def priority(t) -> float:
    score = 0.0
    if t.thumbs == -1 or t.escalated:
        score += 1.0                     # clear failure
    if t.accepted and t.edit_ratio > 0.5:
        score += 0.6                     # accepted, then rewritten
    if t.accepted is False:
        score += 0.3
    return score

def select_for_labeling(traces, budget: int, explore: float = 0.1):
    pool = [scrub_pii(t) for t in traces if t.consent]
    ranked = sorted(pool, key=priority, reverse=True)
    n_rand = int(budget * explore)
    head, tail = ranked[: budget - n_rand], ranked[budget - n_rand :]
